import { Flow } from 'flow-sdk';
import React, { useState, useRef, useCallback, useEffect } from 'react';
import { VideoUploader } from './components/VideoUploader';
import { Sidebar } from './components/Sidebar';
import { Timeline } from './components/Timeline';
import { Icon } from './components/Icon';
import { MediaState, EffectLayer, MoshMode } from './types';
import { WebGLGlitchEngine, getDefaultParams, EFFECT_PARAMS } from './services/webglGlitchEngine';
import { AudioGlitchEngine } from './services/audioGlitchEngine';
import { exportLiveCanvas } from './services/exporter';

function makeLayer(mode: EffectLayer['mode'], enabled = true): EffectLayer {
    return {
        id: Math.random().toString(36).substr(2, 9),
        mode,
        intensity: 75,
        params: getDefaultParams(mode),
        enabled,
    };
}

// ── Runtime injection of fonts + global CSS (index.html is ignored in Flow sandbox) ──
const INJECTED_STYLE_ID = 'weirdcore-global-styles';
const INJECTED_FONT_ID = 'weirdcore-material-symbols';
const INJECTED_BODY_FONT_ID = 'weirdcore-faculty-glyphic';

function useGlobalStyles() {
    useEffect(() => {
        const preconnect1 = document.createElement('link');
        preconnect1.rel = 'preconnect';
        preconnect1.href = 'https://fonts.googleapis.com';
        document.head.appendChild(preconnect1);

        const preconnect2 = document.createElement('link');
        preconnect2.rel = 'preconnect';
        preconnect2.href = 'https://fonts.gstatic.com';
        preconnect2.crossOrigin = 'anonymous';
        document.head.appendChild(preconnect2);

        if (!document.getElementById(INJECTED_FONT_ID)) {
            const fontLink = document.createElement('link');
            fontLink.id = INJECTED_FONT_ID;
            fontLink.rel = 'stylesheet';
            fontLink.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
            document.head.appendChild(fontLink);
        }

        if (!document.getElementById(INJECTED_BODY_FONT_ID)) {
            const bodyFont = document.createElement('link');
            bodyFont.id = INJECTED_BODY_FONT_ID;
            bodyFont.rel = 'stylesheet';
            bodyFont.href = 'https://fonts.googleapis.com/css2?family=Faculty+Glyphic&display=swap';
            document.head.appendChild(bodyFont);
        }

        if (!document.getElementById(INJECTED_STYLE_ID)) {
            const style = document.createElement('style');
            style.id = INJECTED_STYLE_ID;
            style.textContent = `\n                * { box-sizing: border-box; }\n                .material-symbols-rounded { font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 20; }\n\n                /* Tailwind overrides — match original tailwind.config custom theme */\n                .rounded-lg { border-radius: 0.25rem !important; }\n                .rounded-xl { border-radius: 0.375rem !important; }\n                .rounded-2xl { border-radius: 0.5rem !important; }\n                .rounded-3xl { border-radius: 0.75rem !important; }\n                .rounded-full { border-radius: 1rem !important; }\n                .font-sans, html, body, #root {\n                    font-family: 'Faculty Glyphic', -apple-system, BlinkMacSystemFont, sans-serif !important;\n                }\n\n                input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; }\n                input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #5a4339; border-radius: 9999px; }\n                input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 10px; height: 10px; border-radius: 50%; background: #e6d8d3; box-shadow: none; margin-top: -3.5px; cursor: pointer; }\n                input[type=range]::-moz-range-track { width: 100%; height: 3px; background: #5a4339; border-radius: 9999px; }\n                input[type=range]::-moz-range-thumb { width: 10px; height: 10px; border: none; border-radius: 50%; background: #e6d8d3; box-shadow: none; cursor: pointer; }\n\n                .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #4d3732 transparent; }\n                .dark-scrollbar::-webkit-scrollbar { width: 4px; }\n                .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }\n                .dark-scrollbar::-webkit-scrollbar-thumb { background: #4d3732; border-radius: 9999px; }\n                .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #5a4339; }\n\n                @keyframes layer-pop-in { 0% { opacity: 0; transform: translateY(-6px) scale(0.97); } 100% { opacity: 1; transform: translateY(0) scale(1); } }\n\n                html, body, #root {\n                    margin: 0; padding: 0; width: 100%; height: 100%;\n                    background: #171110;\n                    -webkit-font-smoothing: antialiased;\n                    -moz-osx-font-smoothing: grayscale;\n                }\n            `;
            document.head.appendChild(style);
        }

        return () => {
            preconnect1.remove();
            preconnect2.remove();
        };
    }, []);
}

export default function App() {
    useGlobalStyles();

    const [sourceMedia, setSourceMedia] = useState<MediaState | null>(null);
    const [duration, setDuration] = useState(0);
    const [currentTime, setCurrentTime] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);

    const [layers, setLayers] = useState<EffectLayer[]>([{
        ...makeLayer('deepfry'),
        intensity: 50,
        params: { ...getDefaultParams('deepfry'), Sharpen: 0.20, Contrast: 0.25 },
    }]);
    const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);

    const [isProcessing, setIsProcessing] = useState(false);
    const [progress, setProgress] = useState(0);
    const [statusMsg, setStatusMsg] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [isMuted, setIsMuted] = useState(true);
    const [exportedMedia, setExportedMedia] = useState<{ url: string; blob: Blob } | null>(null);

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const engineRef = useRef<WebGLGlitchEngine | null>(null);
    const audioEngineRef = useRef<AudioGlitchEngine | null>(null);
    const isScrubbingRef = useRef(false);
    const wasPlayingBeforeScrubRef = useRef(false);
    const layersRef = useRef(layers);
    const currentTimeRef = useRef(0);
    const sourceFpsRef = useRef(24);
    const sourceMediaRef = useRef(sourceMedia);

    // Sync layersRef safely
    useEffect(() => { layersRef.current = layers; }, [layers]);
    useEffect(() => { sourceMediaRef.current = sourceMedia; }, [sourceMedia]);

    useEffect(() => {
        if (!selectedLayerId && layers.length > 0) {
            setSelectedLayerId(layers[0].id);
        }
    }, [layers, selectedLayerId]);

    const renderOnce = useCallback(() => {
        const video = videoRef.current;
        const engine = engineRef.current;
        if (!video || !engine || video.readyState < 2) return;
        const needsHist = engine.needsHistory(layersRef.current);
        engine.updateVideoTexture(video, needsHist);
        engine.renderStack(layersRef.current, video.currentTime);
    }, []);

    const syncAudio = useCallback((newLayers: EffectLayer[]) => {
        audioEngineRef.current?.updateStack(newLayers);
    }, []);

    useEffect(() => {
        const canvas = canvasRef.current;
        const video = videoRef.current;
        if (!canvas || !video || !sourceMedia) return;

        let engine: WebGLGlitchEngine;
        try {
            engine = new WebGLGlitchEngine(canvas);
        } catch (e) {
            console.error('Failed to init WebGL engine:', e);
            return;
        }
        engineRef.current = engine;

        if (video.readyState >= 2) {
            const needsHist = engine.needsHistory(layersRef.current);
            engine.updateVideoTexture(video, needsHist);
            engine.renderStack(layersRef.current, video.currentTime);
        }

        let active = true;
        const onFrame = () => {
            if (!active) return;
            const needsHist = engine.needsHistory(layersRef.current);
            engine.updateVideoTexture(video, needsHist);
            engine.renderStack(layersRef.current, video.currentTime);
            video.requestVideoFrameCallback(onFrame);
        };
        video.requestVideoFrameCallback(onFrame);

        return () => {
            active = false;
            engine.destroy();
            engineRef.current = null;
        };
    }, [sourceMedia]);

    useEffect(() => {
        const video = videoRef.current;
        if (!video) return;
        if (audioEngineRef.current) return;
        const audioEngine = new AudioGlitchEngine();
        const connectAudio = () => {
            if (audioEngineRef.current) return;
            audioEngine.connect(video);
            audioEngine.setMuted(isMuted);
            audioEngine.updateStack(layersRef.current);
            audioEngineRef.current = audioEngine;
        };
        if (video.readyState >= 2) {
            connectAudio();
        } else {
            video.addEventListener('canplay', connectAudio, { once: true });
        }
        return () => {
            video.removeEventListener('canplay', connectAudio);
        };
    }, [sourceMedia, isMuted]);

    const handleMetadataLoaded = useCallback(() => {
        const vid = videoRef.current;
        if (!vid) return;
        setDuration(vid.duration);
        sourceFpsRef.current = 24;
    }, []);

    const handleCanPlay = useCallback(() => {
        renderOnce();
        if (!isScrubbingRef.current) {
            videoRef.current?.play().catch(() => { });
        }
    }, [renderOnce]);

    const handleSeeked = useCallback(() => {
        renderOnce();
    }, [renderOnce]);

    const handleTimeUpdate = useCallback(() => {
        if (videoRef.current) {
            const t = videoRef.current.currentTime;
            if (Math.abs(t - currentTimeRef.current) > 0.03) {
                currentTimeRef.current = t;
                setCurrentTime(t);
            }
        }
    }, []);

    const handlePlayPause = useCallback(() => {
        const vid = videoRef.current;
        if (!vid) return;
        audioEngineRef.current?.resume();
        if (vid.paused) {
            vid.play();
            setIsPlaying(true);
        } else {
            vid.pause();
            setIsPlaying(false);
        }
    }, []);

    const handleSeek = useCallback((time: number) => {
        if (videoRef.current) {
            if (!isScrubbingRef.current) {
                audioEngineRef.current?.resume();
            }
            videoRef.current.currentTime = time;
            setCurrentTime(time);
            if (isScrubbingRef.current && !wasPlayingBeforeScrubRef.current) {
                videoRef.current.pause();
            }
        }
    }, []);

    const handleScrubStart = useCallback(() => {
        isScrubbingRef.current = true;
        wasPlayingBeforeScrubRef.current = !videoRef.current?.paused;
        if (wasPlayingBeforeScrubRef.current) {
            videoRef.current?.pause();
        }
        audioEngineRef.current?.setMuted(true);
    }, []);

    const handleScrubEnd = useCallback(() => {
        isScrubbingRef.current = false;
        audioEngineRef.current?.setMuted(isMuted);
        if (wasPlayingBeforeScrubRef.current) {
            videoRef.current?.play();
            setIsPlaying(true);
        }
    }, [isMuted]);

    const handleToggleMute = useCallback(() => {
        setIsMuted(prev => {
            const next = !prev;
            audioEngineRef.current?.setMuted(next);
            audioEngineRef.current?.resume();
            return next;
        });
    }, []);

    useEffect(() => {
        const handler = (e: KeyboardEvent) => {
            const active = document.activeElement;
            if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA')) return;
            if (e.key === ' ' || e.code === 'Space') {
                e.preventDefault();
                handlePlayPause();
            }
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [handlePlayPause]);

    const handleAddLayer = useCallback(() => {
        const newLayer = makeLayer('deepfry');
        setLayers(prev => {
            const next = [...prev, newLayer];
            syncAudio(next);
            return next;
        });
        setSelectedLayerId(newLayer.id);
    }, [syncAudio]);

    const handleDeleteLayer = useCallback((id: string) => {
        setLayers(prev => {
            const next = prev.filter(l => l.id !== id);
            syncAudio(next);
            return next;
        });
        setSelectedLayerId(prev => prev === id ? null : prev);
        requestAnimationFrame(renderOnce);
    }, [renderOnce, syncAudio]);

    const handleUpdateLayer = useCallback((id: string, changes: Partial<EffectLayer>) => {
        setLayers(prev => {
            const next = prev.map(l => l.id === id ? { ...l, ...changes } : l);
            syncAudio(next);
            return next;
        });
        requestAnimationFrame(renderOnce);
    }, [renderOnce, syncAudio]);

    const handleToggleLayer = useCallback((id: string) => {
        setLayers(prev => {
            const next = prev.map(l => l.id === id ? { ...l, enabled: !l.enabled } : l);
            syncAudio(next);
            return next;
        });
        requestAnimationFrame(renderOnce);
    }, [renderOnce, syncAudio]);

    const handleMoveLayer = useCallback((id: string, direction: 'up' | 'down') => {
        setLayers(prev => {
            const idx = prev.findIndex(l => l.id === id);
            if (idx < 0) return prev;
            const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
            if (targetIdx < 0 || targetIdx >= prev.length) return prev;
            const next = [...prev];
            [next[idx], next[targetIdx]] = [next[targetIdx], next[idx]];
            syncAudio(next);
            return next;
        });
        requestAnimationFrame(renderOnce);
    }, [renderOnce, syncAudio]);

    const handleRandomize = useCallback(() => {
        const allModes: MoshMode[] = ['deepfry', 'cutter', 'smooth', 'vhs', 'emboss', 'shake', 'blocks', 'drift', 'melt', 'echo'];
        const current = layersRef.current;

        if (current.length > 3) {
            const randomized = current.map(layer => {
                const newIntensity = 30 + Math.floor(Math.random() * 70);
                const defs = EFFECT_PARAMS[layer.mode];
                const params: Record<string, number> = {};
                defs.forEach(d => {
                    params[d.label] = d.min + Math.random() * (d.max - d.min);
                });
                return { ...layer, intensity: newIntensity, params };
            });
            setLayers(randomized);
            syncAudio(randomized);
        } else {
            const shuffled = [...allModes].sort(() => Math.random() - 0.5);
            const picked = shuffled.slice(0, 3);
            const newLayers = picked.map(mode => {
                const layer = makeLayer(mode);
                layer.intensity = 30 + Math.floor(Math.random() * 70);
                const defs = EFFECT_PARAMS[mode];
                const params: Record<string, number> = {};
                defs.forEach(d => {
                    params[d.label] = d.min + Math.random() * (d.max - d.min);
                });
                layer.params = params;
                return layer;
            });
            setLayers(newLayers);
            setSelectedLayerId(newLayers[0].id);
            syncAudio(newLayers);
        }
        requestAnimationFrame(renderOnce);
    }, [renderOnce, syncAudio]);

    const handleSelectMedia = useCallback(async () => {
        try {
            const media = await Flow.media.select({ filter: 'video' });
            if (media) {
                const prev = sourceMediaRef.current;
                if (prev?.dataUrl) URL.revokeObjectURL(prev.dataUrl);
                engineRef.current?.destroy();
                engineRef.current = null;

                const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
                const blob = new Blob([bytes], { type: media.mimeType });
                const dataUrl = URL.createObjectURL(blob);
                setSourceMedia({ id: media.mediaId, dataUrl, name: media.name || 'video.mp4', type: 'video', file: new File([blob], media.name || 'video.mp4', { type: media.mimeType }) });
                setExportedMedia(null);
                setError(null);
            }
        } catch (err) {
            console.error('Failed to load video', err);
        }
    }, []);

    // ─── Export ───
    const handleRender = useCallback(async () => {
        if (!videoRef.current || !canvasRef.current) return;
        setIsProcessing(true);
        setProgress(0);
        setError(null);
        setStatusMsg('Starting render...');

        // Ensure audio flows for recording, but mute speakers so user doesn't hear it
        audioEngineRef.current?.setMuted(false);
        audioEngineRef.current?.resume();
        audioEngineRef.current?.mutePlayback();

        try {
            const audioStream = audioEngineRef.current?.getAudioStream() ?? null;
            const result = await exportLiveCanvas(
                canvasRef.current,
                videoRef.current,
                audioStream,
                sourceFpsRef.current,
                (p) => setProgress(Math.round(p * 100)),
                (msg) => setStatusMsg(msg),
            );
            setExportedMedia(result);
            setStatusMsg('');
            // Pause background playback while preview is open
            videoRef.current?.pause();
            setIsPlaying(false);
        } catch (err: any) {
            setError(`Render failed: ${err.message || 'Unknown error'}`);
            console.error(err);
        } finally {
            // Restore speaker output and mute state
            audioEngineRef.current?.unmutePlayback();
            audioEngineRef.current?.setMuted(isMuted);
            setIsProcessing(false);
        }
    }, [isMuted]);

    // ─── Ensure video is paused while export preview is open ───
    useEffect(() => {
        if (exportedMedia) {
            videoRef.current?.pause();
            setIsPlaying(false);
        }
    }, [exportedMedia]);

    // ─── Close export preview ───
    const handleCloseExport = useCallback(() => {
        if (exportedMedia?.url) URL.revokeObjectURL(exportedMedia.url);
        setExportedMedia(null);
        // Always stay paused after render
    }, [exportedMedia]);

    return (
        <div className="fixed inset-0 w-screen h-screen bg-[#171110] text-[#e0d6d0] flex overflow-hidden font-sans">

            {/* Main workspace */}
            <div className="flex-1 flex flex-col min-w-0 h-full p-8 lg:p-12 overflow-hidden">
                {/* Stage */}
                <div className="flex-1 flex items-center justify-center min-h-0 relative mb-4 overflow-hidden">
                    {sourceMedia ? (
                        <div className="relative w-full h-full flex items-center justify-center">
                            {/* Hidden video — autoplay + loop + muted for instant start */}
                            <video
                                ref={videoRef}
                                src={sourceMedia.dataUrl}
                                onLoadedMetadata={handleMetadataLoaded}
                                onCanPlay={handleCanPlay}
                                onSeeked={handleSeeked}
                                onTimeUpdate={handleTimeUpdate}
                                onPlay={() => setIsPlaying(true)}
                                onPause={() => setIsPlaying(false)}
                                onEnded={() => setIsPlaying(false)}
                                className="hidden"
                                crossOrigin="anonymous"
                                playsInline
                                autoPlay
                                loop
                                muted
                            />

                            {/* WebGL output canvas */}
                            <canvas
                                ref={canvasRef}
                                className="max-w-full max-h-full rounded-2xl border border-[rgba(218,220,224,0.15)] shadow-2xl"
                                style={{ aspectRatio: 'auto' }}
                            />

                            {/* Processing overlay */}
                            {isProcessing && (
                                <div className="absolute inset-0 bg-black/70 backdrop-blur-sm rounded-2xl flex flex-col items-center justify-center gap-4">
                                    <Icon name="progress_activity" size={32} className="animate-spin text-white/80" />
                                    <div className="w-48 space-y-2">
                                        <div className="h-1 bg-white/10 rounded-full overflow-hidden">
                                            <div className="h-full bg-white transition-all duration-300" style={{ width: `${progress}%` }} />
                                        </div>
                                        <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] block text-center">
                                            {statusMsg || `Rendering ${progress}%`}
                                        </span>
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <VideoUploader onSelect={handleSelectMedia} />
                    )}
                </div>

                {/* Timeline scrubber */}
                {sourceMedia && duration > 0 && (
                    <div className="shrink-0 w-full max-w-5xl mx-auto px-6">
                        <Timeline
                            duration={duration}
                            currentTime={currentTime}
                            isPlaying={isPlaying}
                            isMuted={isMuted}
                            onPlayPause={handlePlayPause}
                            onSeek={handleSeek}
                            onToggleMute={handleToggleMute}
                            onScrubStart={handleScrubStart}
                            onScrubEnd={handleScrubEnd}
                        />
                    </div>
                )}

                {/* Error */}
                {error && (
                    <div className="mt-4 mx-auto max-w-5xl px-6 w-full">
                        <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-2 text-red-400 text-[11px]">
                            <Icon name="error" size={16} />
                            {error}
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar */}
            <Sidebar
                layers={layers}
                selectedLayerId={selectedLayerId}
                onSelectLayer={setSelectedLayerId}
                onUpdateLayer={handleUpdateLayer}
                onToggleLayer={handleToggleLayer}
                onAddLayer={handleAddLayer}
                onDeleteLayer={handleDeleteLayer}
                onMoveLayer={handleMoveLayer}
                onRandomize={handleRandomize}
                onSelectMedia={handleSelectMedia}
                onRender={handleRender}
                isProcessing={isProcessing}
                progress={progress}
                statusMsg={statusMsg}
                hasMedia={!!sourceMedia}
            />

            {/* ─── Export Preview Popup ─── */}
            {exportedMedia && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-6"
                    onClick={handleCloseExport}>
                    <div className="bg-[#171110] border border-[rgba(218,220,224,0.15)] rounded-xl p-5 shadow-2xl max-w-4xl w-full flex flex-col gap-5"
                        onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-between">
                            <h2 className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">
                                Render Complete
                            </h2>
                            <button onClick={handleCloseExport}
                                className="text-[rgba(218,220,224,0.35)] hover:text-white transition-colors p-1">
                                <Icon name="close" size={16} />
                            </button>
                        </div>

                        <div className="rounded-xl overflow-hidden bg-black border border-[rgba(218,220,224,0.15)] flex items-center justify-center">
                            <video src={exportedMedia.url} controls autoPlay loop className="max-h-[75vh] max-w-full object-contain" />
                        </div>

                        <div className="flex gap-[5px] pt-2">
                            <button onClick={handleCloseExport}
                                className="flex-1 h-[34px] rounded-xl border border-[rgba(218,220,224,0.15)] hover:bg-white/5 active:bg-white/10 text-[12px] font-medium text-white tracking-[0.1px] transition-all cursor-pointer select-none">
                                Close
                            </button>
                            <button onClick={async () => {
                                if (!exportedMedia) return;
                                try {
                                    const reader = new FileReader();
                                    reader.onloadend = async () => {
                                        const base64 = (reader.result as string).split(',')[1];
                                        await Flow.save({
                                            base64,
                                            mimeType: 'video/mp4',
                                            name: 'Weirdcore Export'
                                        });
                                    };
                                    reader.readAsDataURL(exportedMedia.blob);
                                } catch(err) {
                                    console.error('Save failed:', err);
                                }
                            }}
                                className="flex-1 h-[34px] rounded-xl bg-white hover:bg-gray-200 active:bg-gray-300 text-[12px] font-medium text-black tracking-[0.1px] transition-all cursor-pointer select-none flex items-center justify-center gap-1">
                                <Icon name="download" size={16} />
                                Save to Gallery
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useId } from 'react';

type EffectName = 'liquid' | 'trail' | 'bloom' | 'stutter' | 'reverse' | 'pulse' | 'shatter' | 'transition' | 'melt' | 'echo';

export const CrustyIcon: React.FC<{ name: EffectName | string; className?: string; size?: number; style?: React.CSSProperties }> = ({ name, className = '', size = 16, style }) => {
    const filterId = useId();
    return (
        <svg 
            width={size} 
            height={size} 
            viewBox="0 0 24 24" 
            fill="none" 
            stroke="currentColor" 
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            className={className}
            style={style}
        >
            <defs>
                <filter id={filterId} x="-20%" y="-20%" width="140%" height="140%">
                    <feTurbulence type="fractalNoise" baseFrequency="0.6" numOctaves="3" result="noise" />
                    <feDisplacementMap in="SourceGraphic" in2="noise" scale="2.5" xChannelSelector="R" yChannelSelector="G" />
                </filter>
            </defs>
            <g filter={`url(#${filterId})`}>
            {name === 'liquid' && (
                <>
                    <path d="M11 2 C8 6 6 11 5 15 C3 21 9 23 11 21 C15 23 20 18 16 12 C15 9 13 5 11 2 Z" fill="none" strokeWidth="1" />
                    <path d="M12 3 C10 8 7 12 7 16 C6 20 10 22 13 22 C17 21 19 16 17 11 C15 6 13 4 12 3 Z" fill="none" strokeWidth="1.5" />
                    <path d="M9 13 Q12 18 15 15" strokeWidth="1" strokeDasharray="1 3" />
                </>
            )}
            {name === 'trail' && (
                <>
