import React, { useRef, useCallback, memo, useEffect } from 'react';
import { Icon } from './Icon';

interface TimelineProps {
    duration: number;
    currentTime: number;
    isPlaying: boolean;
    isMuted: boolean;
    onPlayPause: () => void;
    onSeek: (time: number) => void;
    onToggleMute: () => void;
    onScrubStart?: () => void;
    onScrubEnd?: () => void;
}

export const Timeline: React.FC<TimelineProps> = memo(({
    duration, currentTime, isPlaying, isMuted, onPlayPause, onSeek, onToggleMute, onScrubStart, onScrubEnd
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const playheadRef = useRef<HTMLDivElement>(null);

    const durationRef = useRef(duration);
    durationRef.current = duration;
    const onSeekRef = useRef(onSeek);
    onSeekRef.current = onSeek;
    const onScrubStartRef = useRef(onScrubStart);
    onScrubStartRef.current = onScrubStart;
    const onScrubEndRef = useRef(onScrubEnd);
    onScrubEndRef.current = onScrubEnd;

    // Update playhead position
    useEffect(() => {
        if (playheadRef.current && duration > 0) {
            playheadRef.current.style.left = `${(currentTime / duration) * 100}%`;
        }
    }, [currentTime, duration]);

    const getTimeFromX = useCallback((clientX: number) => {
        if (!containerRef.current || durationRef.current === 0) return 0;
        const rect = containerRef.current.getBoundingClientRect();
        const padding = 4;
        const width = rect.width - padding * 2;
        const x = clientX - rect.left - padding;
        return Math.max(0, Math.min(1, x / width)) * durationRef.current;
    }, []);

    const handleTrackMouseDown = useCallback((e: React.MouseEvent) => {
        onScrubStartRef.current?.();
        onSeekRef.current(getTimeFromX(e.clientX));
        const onMove = (ev: MouseEvent) => onSeekRef.current(getTimeFromX(ev.clientX));
        const onUp = () => {
            onScrubEndRef.current?.();
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [getTimeFromX]);

    if (duration === 0) return null;

    const progress = (currentTime / duration) * 100;

    return (
        <div className="w-full select-none flex flex-col">
            {/* Controls */}
            <div className="flex items-center justify-between px-1 mb-4">
                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1">
                        <button onClick={onPlayPause}
                            className="w-[34px] h-[34px] flex items-center justify-center rounded-xl bg-[#2a1f1c] hover:bg-[#3a2c28] active:bg-[#4a3631] transition-colors text-white shadow-[inset_1.5px_1.5px_3px_rgba(255,255,255,0.1),inset_-2px_-2px_4px_rgba(0,0,0,0.5)]">
                            <Icon name={isPlaying ? 'pause' : 'play_arrow'} size={18} filled />
                        </button>
                    </div>
                    <span className="text-[13px] font-medium tracking-[0.1px] text-[rgba(255,255,255,0.45)] tabular-nums">
                        {formatTime(currentTime)}
                    </span>
                </div>
                <div className="flex items-center gap-3">
                    <span className="text-[13px] font-medium tracking-[0.1px] text-[rgba(255,255,255,0.45)] tabular-nums">
                        {formatTime(duration)}
                    </span>
                    {/* Audio mute toggle */}
                    <button onClick={onToggleMute}
                        className={`w-[34px] h-[34px] flex items-center justify-center rounded-xl bg-[#2a1f1c] hover:bg-[#3a2c28] active:bg-[#4a3631] transition-colors shadow-[inset_1.5px_1.5px_3px_rgba(255,255,255,0.1),inset_-2px_-2px_4px_rgba(0,0,0,0.5)]\n                            ${isMuted ? 'text-white/25' : 'text-white'}`}>
                        <Icon name={isMuted ? 'volume_off' : 'volume_up'} size={18} filled />
                    </button>
                </div>
            </div>

            {/* Hit area wrapper — extends above the visible track for easier scrubbing */}
            <div
                ref={containerRef}
                onMouseDown={handleTrackMouseDown}
                className="relative w-full cursor-pointer"
                style={{ paddingTop: '12px', marginTop: '-12px' }}
            >
                {/* Visible scrubber bar */}
                <div className="relative h-[28px] w-full bg-transparent rounded-xl border border-[#5a4339] p-1 group">
                    <div className="absolute inset-x-1 inset-y-0">
                        {/* Progress fill */}
                        <div
                            className="absolute top-1 bottom-1 left-0 rounded-lg bg-[#a68a7c]/30"
                            style={{ width: `${progress}%` }}
                        />

                        {/* Playhead */}
                        <div
                            ref={playheadRef}
                            className="absolute top-0 bottom-0 w-px bg-[#e6d8d3]/80 z-40 pointer-events-none will-change-[left]"
                            style={{ left: `${progress}%` }}
                        >
                            <div className="absolute -top-1 left-1/2 -translate-x-1/2 w-3.5 h-3.5 bg-[#e6d8d3] rounded-full" />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
});

function formatTime(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
}

