import { EffectLayer, MoshMode } from '../types';

interface EffectNode {
    input: AudioNode;
    output: AudioNode;
    extra?: AudioNode[]; // for cleanup
    mode: MoshMode; // track which effect created this node
}

/**
 * Manages a Web Audio API effect chain that mirrors the visual effect stack.
 * Each visual effect has a corresponding audio effect.
 */
export class AudioGlitchEngine {
    private ctx: AudioContext | null = null;
    private source: MediaElementAudioSourceNode | null = null;
    private masterGain: GainNode | null = null;
    private destination: MediaStreamAudioDestinationNode | null = null;
    private currentChain: EffectNode[] = [];
    private chainSignature = ''; // tracks topology to avoid unnecessary rebuilds
    private muted = false;
    private connected = false;
    private videoEl: HTMLVideoElement | null = null;

    connect(video: HTMLVideoElement) {
        if (this.connected) return;

        this.videoEl = video;
        this.ctx = new AudioContext();
        this.source = this.ctx.createMediaElementSource(video);
        this.masterGain = this.ctx.createGain();
        this.destination = this.ctx.createMediaStreamDestination();

        // Route: source → gain → speakers + recording destination
        this.source.connect(this.masterGain);
        this.masterGain.connect(this.ctx.destination);
        this.masterGain.connect(this.destination);

        // Unmute the HTML video element — audio now flows through Web Audio
        // (masterGain controls perceived volume, not the element's muted property)
        video.muted = false;

        this.connected = true;
    }

    setMuted(muted: boolean) {
        this.muted = muted;
        if (this.masterGain) {
            this.masterGain.gain.value = muted ? 0 : 1;
        }
    }

    isMuted() {
        return this.muted;
    }

    getAudioStream(): MediaStream | null {
        return this.destination?.stream ?? null;
    }

    getContext(): AudioContext | null {
        return this.ctx;
    }

    /** Rebuild the audio effect chain to match the current layer stack */
    updateStack(layers: EffectLayer[]) {
        if (!this.ctx || !this.source || !this.masterGain || !this.destination) return;

        const enabled = layers.filter(l => l.enabled && l.intensity > 0);

        // Compute a signature from the chain topology (modes in order)
        const sig = enabled.map(l => l.mode).join(',');

        // If topology hasn't changed, just update parameters in-place (no click/pop)
        if (sig === this.chainSignature && this.currentChain.length === enabled.length) {
            this.updateParams(enabled);
            return;
        }

        // Topology changed — full rebuild
        this.source.disconnect();
        for (const node of this.currentChain) {
            node.input.disconnect();
            node.output.disconnect();
            node.extra?.forEach(n => n.disconnect());
        }
        this.currentChain = [];

        if (enabled.length === 0) {
            // Straight through
            this.source.connect(this.masterGain);
            this.masterGain.connect(this.ctx.destination);
            this.masterGain.connect(this.destination);
            this.chainSignature = sig;
            return;
        }

        // Build effect nodes for enabled layers
        const nodes: EffectNode[] = [];
        for (const layer of enabled) {
            const node = this.createEffectNode(layer);
            if (node) nodes.push(node);
        }

        // Chain: source → node1 → node2 → ... → masterGain → dest
        let prev: AudioNode = this.source;
        for (const node of nodes) {
            prev.connect(node.input);
            prev = node.output;
        }
        prev.connect(this.masterGain);
        this.masterGain.connect(this.ctx.destination);
        this.masterGain.connect(this.destination);

        this.currentChain = nodes;
        this.chainSignature = sig;
    }

    /** Update AudioParam values on existing nodes without rebuilding the chain */
    private updateParams(layers: EffectLayer[]) {
        if (!this.ctx) return;
        for (let i = 0; i < layers.length && i < this.currentChain.length; i++) {
            const layer = layers[i];
            const node = this.currentChain[i];
            const intensity = layer.intensity / 100;
            this.applyParams(node, layer.mode, intensity, layer.params);
        }
    }

    /** Apply parameter values to an existing effect node */
    private applyParams(node: EffectNode, mode: MoshMode, intensity: number, params: Record<string, number>) {
        if (!this.ctx) return;
        const t = this.ctx.currentTime;
        const ramp = 0.02; // 20ms ramp to avoid clicks

        switch (mode) {
            case 'deepfry': {
                const shaper = node.input as WaveShaperNode;
                const amount = (params['Sharpen'] ?? 0.6) * intensity * 50;
                const samples = 256;
                const curve = new Float32Array(samples);
                for (let i = 0; i < samples; i++) {
                    const x = (i * 2) / samples - 1;
                    curve[i] = (Math.PI + amount) * x / (Math.PI + amount * Math.abs(x));
                }
                shaper.curve = curve;
                break;
            }
            case 'cutter': {
                const gain = node.input as GainNode;
                const lfo = node.extra?.[0] as OscillatorNode;
                const lfoGain = node.extra?.[1] as GainNode;
                if (lfo) lfo.frequency.setTargetAtTime((params['Jump Rate'] ?? 0.4) * 15 + 1, t, ramp);
                if (lfoGain) lfoGain.gain.setTargetAtTime(intensity * 0.8, t, ramp);
                if (gain) gain.gain.setTargetAtTime(1 - intensity * 0.3, t, ramp);
                break;
            }
            case 'smooth': {
                const filter = node.input as BiquadFilterNode;
                filter.frequency.setTargetAtTime(20000 - intensity * (params['Blur'] ?? 0.4) * 18000, t, ramp);
                filter.Q.setTargetAtTime((params['Dreamy'] ?? 0.2) * intensity * 8, t, ramp);
                break;
            }
            case 'vhs': {
                const filter = node.input as BiquadFilterNode;
                filter.frequency.setTargetAtTime(800 + (1 - intensity) * 2000, t, ramp);
                filter.Q.setTargetAtTime((params['Color Bleed'] ?? 0.5) * intensity * 6 + 0.5, t, ramp);
                break;
            }
            case 'emboss': {
                const filter = node.input as BiquadFilterNode;
                filter.frequency.setTargetAtTime(2000 + (params['Direction'] ?? 0.15) * 4000, t, ramp);
                filter.Q.setTargetAtTime((params['Metallic'] ?? 0.2) * intensity * 15 + 1, t, ramp);
                filter.gain.setTargetAtTime(intensity * (params['Depth'] ?? 0.5) * 18, t, ramp);
                break;
            }
            case 'shake': {
                const lfo = node.extra?.[0] as OscillatorNode;
                const lfoGain = node.extra?.[1] as GainNode;
                if (lfo) lfo.frequency.setTargetAtTime((params['Speed'] ?? 0.4) * 30 + 5, t, ramp);
                if (lfoGain) lfoGain.gain.setTargetAtTime(intensity * 0.6, t, ramp);
                break;
            }
            case 'blocks': {
                const filter = node.input as BiquadFilterNode;
                filter.frequency.setTargetAtTime(20000 - intensity * (params['Grid Size'] ?? 0.4) * 19000, t, ramp);
                filter.Q.setTargetAtTime(intensity * (params['Scale Chaos'] ?? 0.5) * 20, t, ramp);
                break;
            }
            case 'drift': {
                const panner = node.input as StereoPannerNode;
                const panAmount = ((params['Direction'] ?? 0) * 2 - 1) * intensity;
                panner.pan.setTargetAtTime(panAmount, t, ramp);
                break;
            }
            case 'melt': {
                const filter = node.input as BiquadFilterNode;
                filter.frequency.setTargetAtTime(20000 - intensity * (params['Flow Speed'] ?? 0.4) * 19500, t, ramp);
                filter.Q.setTargetAtTime(intensity * (params['Drip'] ?? 0.3) * 12, t, ramp);
                break;
            }
            case 'echo': {
                const delay = node.extra?.[0] as DelayNode;
                const feedback = node.extra?.[2] as GainNode;
                const wet = node.extra?.[1] as GainNode;
                if (delay) delay.delayTime.setTargetAtTime((params['Offset'] ?? 0.3) * 0.8 + 0.05, t, ramp);
                if (feedback) feedback.gain.setTargetAtTime((params['Decay'] ?? 0.6) * intensity * 0.85, t, ramp);
                if (wet) wet.gain.setTargetAtTime(intensity * 0.7, t, ramp);
                break;
            }
        }
    }

    private createEffectNode(layer: EffectLayer): EffectNode | null {
        if (!this.ctx) return null;
        const intensity = layer.intensity / 100;

        switch (layer.mode) {
            case 'deepfry': return this.makeDistortion(intensity, layer.params);
            case 'cutter': return this.makeTremolo(intensity, layer.params);
            case 'smooth': return this.makeLowpass(intensity, layer.params);
            case 'vhs': return this.makeBandpass(intensity, layer.params);
            case 'emboss': return this.makeResonance(intensity, layer.params);
            case 'shake': return this.makeFastTremolo(intensity, layer.params);
            case 'blocks': return this.makeBitcrush(intensity, layer.params);
            case 'drift': return this.makeStereoShift(intensity, layer.params);
            case 'melt': return this.makeMuffle(intensity, layer.params);
            case 'echo': return this.makeDelay(intensity, layer.params);
            default: return null;
        }
    }

    /** Deep Fry: hard-clip distortion waveshaper */
    private makeDistortion(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const shaper = ctx.createWaveShaper();
        const amount = (params['Sharpen'] ?? 0.6) * intensity * 50;
        const samples = 256;
        const curve = new Float32Array(samples);
        for (let i = 0; i < samples; i++) {
            const x = (i * 2) / samples - 1;
            curve[i] = (Math.PI + amount) * x / (Math.PI + amount * Math.abs(x));
        }
        shaper.curve = curve;
        shaper.oversample = '4x';
        return { input: shaper, output: shaper, mode: 'deepfry' };
    }

    /** Cutter: slow tremolo (volume chops) */
    private makeTremolo(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const gain = ctx.createGain();
        const lfo = ctx.createOscillator();
        const lfoGain = ctx.createGain();

        lfo.type = 'square';
        lfo.frequency.value = (params['Jump Rate'] ?? 0.4) * 15 + 1;
        lfoGain.gain.value = intensity * 0.8;

        lfo.connect(lfoGain);
        lfoGain.connect(gain.gain);
        lfo.start();
        gain.gain.value = 1 - intensity * 0.3;

        return { input: gain, output: gain, extra: [lfo, lfoGain], mode: 'cutter' };
    }

    /** Smooth: lowpass filter — muffled dreamy sound */
    private makeLowpass(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 20000 - intensity * (params['Blur'] ?? 0.4) * 18000;
        filter.Q.value = (params['Dreamy'] ?? 0.2) * intensity * 8;
        return { input: filter, output: filter, mode: 'smooth' };
    }

    /** VHS: bandpass — tinny, lo-fi telephone sound */
    private makeBandpass(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.value = 800 + (1 - intensity) * 2000;
        filter.Q.value = (params['Color Bleed'] ?? 0.5) * intensity * 6 + 0.5;
        return { input: filter, output: filter, mode: 'vhs' };
    }

    /** Emboss: sharp resonant peak — metallic ring */
    private makeResonance(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const filter = ctx.createBiquadFilter();
        filter.type = 'peaking';
        filter.frequency.value = 2000 + (params['Direction'] ?? 0.15) * 4000;
        filter.Q.value = (params['Metallic'] ?? 0.2) * intensity * 15 + 1;
        filter.gain.value = intensity * (params['Depth'] ?? 0.5) * 18;
        return { input: filter, output: filter, mode: 'emboss' };
    }

    /** Shake: fast tremolo — jittery modulation */
    private makeFastTremolo(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const gain = ctx.createGain();
        const lfo = ctx.createOscillator();
        const lfoGain = ctx.createGain();

        lfo.type = 'sine';
        lfo.frequency.value = (params['Speed'] ?? 0.4) * 30 + 5;
        lfoGain.gain.value = intensity * 0.6;

        lfo.connect(lfoGain);
        lfoGain.connect(gain.gain);
        lfo.start();

        return { input: gain, output: gain, extra: [lfo, lfoGain], mode: 'shake' };
    }

    /** Blocks: aggressive lowpass with high resonance — underwater warble */
    private makeBitcrush(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 20000 - intensity * (params['Grid Size'] ?? 0.4) * 19000;
        filter.Q.value = intensity * (params['Scale Chaos'] ?? 0.5) * 20;
        return { input: filter, output: filter, mode: 'blocks' };
    }

    /** Drift: stereo panner — sound drifts left/right */
    private makeStereoShift(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const panner = ctx.createStereoPanner();
        const panAmount = ((params['Direction'] ?? 0) * 2 - 1) * intensity;
        panner.pan.value = panAmount;
        return { input: panner, output: panner, mode: 'drift' };
    }

    /** Melt: very low lowpass — everything goes thick and muffled */
    private makeMuffle(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 20000 - intensity * (params['Flow Speed'] ?? 0.4) * 19500;
        filter.Q.value = intensity * (params['Drip'] ?? 0.3) * 12;

        // Add warmth (slight overdrive)
        if (intensity > 0.3) {
            const shaper = ctx.createWaveShaper();
            const curve = new Float32Array(256);
            for (let i = 0; i < 256; i++) {
                const x = (i * 2) / 256 - 1;
                curve[i] = Math.tanh(x * (1 + intensity * 2));
            }
            shaper.curve = curve;
            filter.connect(shaper);
            return { input: filter, output: shaper, extra: [], mode: 'melt' };
        }

        return { input: filter, output: filter, mode: 'melt' };
    }

    /** Echo: delay with feedback — ghostly repeats */
    private makeDelay(intensity: number, params: Record<string, number>): EffectNode {
        const ctx = this.ctx!;
        const dry = ctx.createGain();
        const wet = ctx.createGain();
        const delay = ctx.createDelay(2.0);
        const feedback = ctx.createGain();
        const merger = ctx.createGain();

        delay.delayTime.value = (params['Offset'] ?? 0.3) * 0.8 + 0.05;
        feedback.gain.value = (params['Decay'] ?? 0.6) * intensity * 0.85;
        wet.gain.value = intensity * 0.7;
        dry.gain.value = 1;

        // dry path
        dry.connect(merger);
        // wet path with feedback
        dry.connect(delay);
        delay.connect(wet);
        wet.connect(merger);
        delay.connect(feedback);
        feedback.connect(delay);

        return { input: dry, output: merger, extra: [delay, wet, feedback], mode: 'echo' };
    }

    /** Disconnect speakers (still records to destination stream) */
    mutePlayback() {
        if (this.masterGain && this.ctx) {
            try { this.masterGain.disconnect(this.ctx.destination); } catch {}
        }
    }

    /** Reconnect speakers */
    unmutePlayback() {
        if (this.masterGain && this.ctx) {
            try { this.masterGain.connect(this.ctx.destination); } catch {}
        }
    }

    resume() {
        this.ctx?.resume();
    }

    destroy() {
        for (const node of this.currentChain) {
            try { node.input.disconnect(); } catch {}
            try { node.output.disconnect(); } catch {}
            node.extra?.forEach(n => { try { n.disconnect(); } catch {} });
        }
        this.currentChain = [];
        this.chainSignature = '';
        try { this.source?.disconnect(); } catch {}
        try { this.masterGain?.disconnect(); } catch {}
        this.ctx?.close();
        this.ctx = null;
        this.source = null;
        this.masterGain = null;
        this.destination = null;
        this.connected = false;
    }
}

import { Output, Mp4OutputFormat, BufferTarget, EncodedVideoPacketSource, EncodedAudioPacketSource, EncodedPacket } from 'mediabunny';

/**
 * Live-records the glitch canvas + audio into an MP4 via mediabunny.
 * The video plays once from start to end (no loop) during the recording.
 */
export async function exportLiveCanvas(
    canvas: HTMLCanvasElement,
    video: HTMLVideoElement,
    audioStream: MediaStream | null,
    fps: number,
    onProgress: (p: number) => void,
    onStatus: (msg: string) => void,
): Promise<{ url: string; blob: Blob }> {
    onStatus('Initializing exporter...');

    // Stop playback, seek to beginning, disable loop
    video.pause();
    const wasLooping = video.loop;
    video.loop = false;
    video.currentTime = 0;

    await new Promise<void>((res) => {
        const handler = () => { video.removeEventListener('seeked', handler); res(); };
        video.addEventListener('seeked', handler);
    });

    // ─── Mediabunny output setup ───
    const target = new BufferTarget();
    const output = new Output({
        format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
        target,
    });

    // Video track (H.264)
    const videoSource = new EncodedVideoPacketSource('avc');
    output.addVideoTrack(videoSource);

    const videoEncoder = new VideoEncoder({
        output: async (chunk, meta) => {
            try {
                await videoSource.add(
                    EncodedPacket.fromEncodedChunk(chunk),
                    meta ?? undefined,
                );
            } catch (e) {
                console.debug('Video muxer error:', e);
            }
        },
        error: (e) => console.error('VideoEncoder error:', e),
    });

    videoEncoder.configure({
        codec: 'avc1.4d0034',
        width: canvas.width,
        height: canvas.height,
        bitrate: 12_000_000,
        framerate: fps,
        latencyMode: 'quality',
    });

    // Audio track (AAC) — only if we have an audio stream
    let audioEncoder: AudioEncoder | null = null;
    let audioSource: EncodedAudioPacketSource | null = null;
    let audioProcessor: MediaStreamAudioSourceNode | null = null;
    let audioWorkletCtx: AudioContext | null = null;
    let scriptProcessor: ScriptProcessorNode | null = null;

    if (audioStream && audioStream.getAudioTracks().length > 0) {
        audioSource = new EncodedAudioPacketSource('aac');
        output.addAudioTrack(audioSource);

        audioEncoder = new AudioEncoder({
            output: async (chunk, meta) => {
                try {
                    await audioSource!.add(
                        EncodedPacket.fromEncodedChunk(chunk),
                        meta ?? undefined,
                    );
                } catch (e) {
                    console.debug('Audio muxer error:', e);
                }
            },
            error: (e) => console.error('AudioEncoder error:', e),
        });

        audioEncoder.configure({
            codec: 'mp4a.40.2',
            numberOfChannels: 2,
            sampleRate: 48000,
            bitrate: 192_000,
        });

        // Capture audio from stream
        audioWorkletCtx = new AudioContext({ sampleRate: 48000 });
        audioProcessor = audioWorkletCtx.createMediaStreamSource(audioStream);
        scriptProcessor = audioWorkletCtx.createScriptProcessor(4096, 2, 2);

        let audioSampleCount = 0;
        scriptProcessor.onaudioprocess = (e) => {
            if (!audioEncoder || audioEncoder.state !== 'configured') return;
            const left = e.inputBuffer.getChannelData(0);
            const right = e.inputBuffer.getChannelData(1);

            const data = new Float32Array(left.length * 2);
            for (let i = 0; i < left.length; i++) {
                data[i] = left[i];
                data[left.length + i] = right[i];
            }

            const audioData = new AudioData({
                format: 'f32-planar',
                sampleRate: 48000,
                numberOfFrames: left.length,
                numberOfChannels: 2,
                timestamp: Math.floor((audioSampleCount / 48000) * 1_000_000),
                data,
            });

            try {
                audioEncoder.encode(audioData);
            } catch { }
            audioData.close();
            audioSampleCount += left.length;
        };

        audioProcessor.connect(scriptProcessor);
        scriptProcessor.connect(audioWorkletCtx.destination);
    }

    await output.start();
    onStatus('Rendering, please wait...');

    const totalDuration = video.duration;
    const frameDurUsec = 1_000_000 / fps;
    const frameDurSec = 1 / fps;
    let lastFrameTime = -1;
    let recording = true;

    // Use a deferred promise so both rAF and the 'ended' event can signal completion
    let finishResolve: () => void;
    const finishPromise = new Promise<void>(r => { finishResolve = r; });
    let finished = false;

    const markFinished = () => {
        if (finished) return;
        finished = true;
        recording = false;
        finishResolve();
    };

    const renderLoop = () => {
        if (!recording) return;

        // Use video.currentTime for frame timestamp — ensures correct duration
        const videoTimeSec = video.currentTime;
        const timestampUsec = Math.floor(videoTimeSec * 1_000_000);

        // Only encode if enough time has elapsed for the next frame (throttle to target fps)
        if (videoTimeSec - lastFrameTime >= frameDurSec * 0.8) {
            try {
                const isKeyFrame = lastFrameTime < 0 || (videoTimeSec - lastFrameTime) > 1;
                const vf = new VideoFrame(canvas, { timestamp: timestampUsec, duration: Math.floor(frameDurUsec) });
                videoEncoder.encode(vf, { keyFrame: isKeyFrame || Math.floor(videoTimeSec) !== Math.floor(lastFrameTime) });
                vf.close();
                lastFrameTime = videoTimeSec;
            } catch (e) {
                console.warn('Frame capture error:', e);
            }
        }

        onProgress(Math.min(videoTimeSec / totalDuration, 0.99));

        if (video.ended || videoTimeSec >= totalDuration - 0.05) {
            markFinished();
        } else {
            requestAnimationFrame(renderLoop);
        }
    };

    video.addEventListener('ended', markFinished, { once: true });
    video.play();
    requestAnimationFrame(renderLoop);

    // Wait for recording to complete (from either rAF or 'ended' event)
    await finishPromise;

    // ─── Finalize ───
    onStatus('Finalizing MP4...');
    video.pause();
    video.removeEventListener('ended', markFinished);

    await videoEncoder.flush();
    videoEncoder.close();

    if (audioEncoder && audioEncoder.state === 'configured') {
        await audioEncoder.flush();
        audioEncoder.close();
    }

    if (scriptProcessor) {
        scriptProcessor.onaudioprocess = null;
        scriptProcessor.disconnect();
    }
    if (audioProcessor) audioProcessor.disconnect();
    if (audioWorkletCtx) await audioWorkletCtx.close();

    await output.finalize();

    const blob = new Blob([target.buffer], { type: 'video/mp4' });
    const url = URL.createObjectURL(blob);

    video.loop = wasLooping;
    video.currentTime = 0;

    onStatus('Export complete!');
    onProgress(1);
    return { url, blob };
}

import { EffectLayer, MoshMode } from '../types';

